import { FlowingMenu } from "solen-design/react";

const items = [
  { text: "Work", marquee: "Work", image: "/work.png", link: "/work" },
  { text: "Studio", marquee: "Studio", image: "/studio.png" },
  { text: "Journal", marquee: "Journal", link: "/journal", meta: "2025" }
];

<div style={{ height: "70vh" }}>
  <FlowingMenu
    items={items}
    speed={60}
    direction="left"
    followCursor={0.4}
    duration={0.5}
    stretch={0.6}
    magnet={0.25}
    bandInset={0}
    bandRadius={0}
    carryContent={false}
    dividers={true}
    dimInactive={false}
    align="center"
    showIndex={false}
    showArrow={false}
    imageShape="pill"
    intro={true}
    onItemClick={(item, index) => console.log(item, index)}
  />
</div>
